const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'content-type':'application/json; charset=utf-8'}});
const TG=(token,method)=>`https://api.telegram.org/bot${token}/${method}`;
async function telegram(env,method,body){const r=await fetch(TG(env.TELEGRAM_BOT_TOKEN,method),{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify(body)});const d=await r.json();if(!d.ok)throw new Error(`Telegram ${method}: ${d.description||'request failed'}`);return d.result;}
async function supabase(env,path,options={}){const headers={apikey:env.SUPABASE_SERVICE_ROLE_KEY,Authorization:`Bearer ${env.SUPABASE_SERVICE_ROLE_KEY}`,'content-type':'application/json',...(options.headers||{})};const r=await fetch(`${env.SUPABASE_URL}${path}`,{...options,headers});const t=await r.text();let d=null;try{d=t?JSON.parse(t):null}catch{d=t}if(!r.ok)throw new Error(`Supabase ${r.status}: ${typeof d==='string'?d:JSON.stringify(d)}`);return d;}
const esc=s=>String(s??'').replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
const typeLabel=t=>t==='artist'?'Исполнитель':t==='beatmaker'?'Битмейкер':'Не выбран';
const tgUsername=id=>`tg_${String(id).replace(/\D/g,'').slice(-24)}`;
async function getAccount(env,u){const rows=await supabase(env,`/rest/v1/telegram_accounts?telegram_user_id=eq.${u.id}&select=*`);if(rows?.[0])return rows[0];const email=`telegram_${u.id}@nexora.local`;let user;try{user=await supabase(env,'/auth/v1/admin/users',{method:'POST',body:JSON.stringify({email,password:crypto.randomUUID()+crypto.randomUUID(),email_confirm:true,user_metadata:{telegram_user_id:u.id}})});}catch(e){const f=await supabase(env,`/auth/v1/admin/users?email=${encodeURIComponent(email)}`,{method:'GET'}).catch(()=>null);user=f?.users?.[0]||f?.[0];if(!user)throw e}const p=await supabase(env,`/rest/v1/profiles?id=eq.${user.id}&select=id`).catch(()=>[]);if(!p?.[0])await supabase(env,'/rest/v1/profiles',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({id:user.id,username:tgUsername(u.id),display_name:'Nexora user',profile_type:'user'})});const a={telegram_user_id:u.id,profile_id:user.id,telegram_username:u.username||null,first_name:u.first_name||null,last_name:u.last_name||null};await supabase(env,'/rest/v1/telegram_accounts',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify(a)});return a;}
async function session(env,id){const r=await supabase(env,`/rest/v1/telegram_sessions?telegram_user_id=eq.${id}&select=*`);return r?.[0]||{state:'idle',payload:{}}}
async function setSession(env,id,state,payload={}){await supabase(env,'/rest/v1/telegram_sessions',{method:'POST',headers:{Prefer:'resolution=merge-duplicates,return=minimal'},body:JSON.stringify({telegram_user_id:id,state,payload,updated_at:new Date().toISOString()})});}
async function del(env,chat,id){if(id)await telegram(env,'deleteMessage',{chat_id:chat,message_id:id}).catch(()=>null)}
async function send(env,chat,text,markup,account){const r=await telegram(env,'sendMessage',{chat_id:chat,text,parse_mode:'HTML',...(markup?{reply_markup:markup}:{})});if(account){const s=await session(env,account.telegram_user_id);await setSession(env,account.telegram_user_id,s.state,{...(s.payload||{}),last_bot_message_id:r.message_id})}return r}
const cancel=()=>({inline_keyboard:[[{text:'❌ Отменить',callback_data:'flow:cancel'}]]});
function profileKeyboard(p){const artist=p.profile_type==='artist';return{inline_keyboard:[[{text:'✏️ Редактировать профиль',callback_data:'profile:edit'}],[{text:'📢 Добавить Telegram-канал',callback_data:'profile:channel'}],[{text:artist?'🎵 Загрузить свою демку':'🥁 Загрузить свой бит',callback_data:'upload:start'}],[{text:artist?'📂 Мои демки':'📂 Мои биты',callback_data:`library:${artist?'tracks':'beats'}:0`}],[{text:'🤝 Запросы на коллаб',callback_data:'requests:collab'}],...(artist?[[{text:'🎵 Предложенные биты',callback_data:'requests:offers'}]]:[[{text:'📝 Запись бита / Купить бит',callback_data:'requests:beats'}]]),[{text:'🎧 Случайные демки',callback_data:'random:tracks'}],[{text:'🥁 Случайные биты',callback_data:'random:beats'}]]}}
async function getProfile(env,a){const r=await supabase(env,`/rest/v1/profiles?id=eq.${a.profile_id}&select=id,username,display_name,profile_type,telegram_channel`);return r?.[0]||null}
async function showProfile(env,chat,a,messageId=null){const p=await getProfile(env,a);if(!p)return send(env,chat,'Профиль не найден.',null,a);const ch=p.telegram_channel?`\nTelegram: <b>${esc(p.telegram_channel)}</b>`:'';const text=`👤 <b>Профиль Nexora</b>\n\nID: <code>${esc(p.id)}</code>\nИмя профиля: <b>${esc(p.username)}</b>\nТип профиля: <b>${esc(typeLabel(p.profile_type))}</b>${ch}`;const markup=profileKeyboard(p);if(messageId){await telegram(env,'editMessageText',{chat_id:chat,message_id:messageId,text,parse_mode:'HTML',reply_markup:markup}).catch(()=>null);await setSession(env,a.telegram_user_id,'idle',{last_bot_message_id:messageId});return}return send(env,chat,text,markup,a)}
async function registration(env,chat,a,messageId=null){await setSession(env,a.telegram_user_id,'registration_type',{message_id:messageId});const text='👋 <b>Регистрация Nexora</b>\n\nВыбери тип профиля:';const markup={inline_keyboard:[[{text:'🎤 Исполнитель',callback_data:'reg:type:artist'},{text:'🥁 Битмейкер',callback_data:'reg:type:beatmaker'}]]};if(messageId)return telegram(env,'editMessageText',{chat_id:chat,message_id:messageId,text,parse_mode:'HTML',reply_markup:markup});return send(env,chat,text,markup,a)}
async function startRegistration(env,chat,a){const p=await getProfile(env,a);if(p?.profile_type&&p.profile_type!=='user'&&p.username!==tgUsername(a.telegram_user_id))return showProfile(env,chat,a);return registration(env,chat,a)}
async function updateProfile(env,a,patch){return supabase(env,`/rest/v1/profiles?id=eq.${a.profile_id}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify(patch)})}
async function startUpload(env,chat,a){const p=await getProfile(env,a);if(!p||!['artist','beatmaker'].includes(p.profile_type))return send(env,chat,'Сначала закончи регистрацию.',cancel(),a);await setSession(env,a.telegram_user_id,'awaiting_upload',{type:p.profile_type});return send(env,chat,`📤 <b>${p.profile_type==='artist'?'Загрузка демки':'Загрузка бита'}</b>\n\nПришли аудиофайл <b>MP3</b>.`,cancel(),a)}
async function downloadTelegramFile(env,id){const f=await telegram(env,'getFile',{file_id:id});const r=await fetch(`https://api.telegram.org/file/bot${env.TELEGRAM_BOT_TOKEN}/${f.file_path}`);if(!r.ok)throw new Error('Не удалось скачать файл из Telegram');return{bytes:await r.arrayBuffer(),path:f.file_path||''}}
async function storeAudio(env,a,id){const f=await downloadTelegramFile(env,id);if(!f.path.toLowerCase().endsWith('.mp3'))throw new Error('Поддерживается только MP3');const path=`telegram/${a.profile_id}/${crypto.randomUUID()}.mp3`;await supabase(env,`/storage/v1/object/nexora-audio/${path}`,{method:'POST',headers:{'content-type':'audio/mpeg','x-upsert':'false'},body:f.bytes});return path}
function parseGenres(text){return String(text||'').split(',').map(x=>x.trim().replace(/^#+/,'')).filter(Boolean)}
function parseBpmKey(text){const m=String(text||'').trim().match(/^(\d{2,3})\s*BPM\s+(.+)$/i);if(!m||+m[1]<30||+m[1]>300)return null;return{bpm:+m[1],musical_key:m[2].trim()}}
async function uploadPreview(env,chat,a){const s=await session(env,a.telegram_user_id),p=s.payload,url=`${env.SUPABASE_URL}/storage/v1/object/public/nexora-audio/${p.audio_path}`;const caption=`${p.type==='artist'?'🎵':'🥁'} <b>${esc(p.title)}</b>\n${esc(p.genres.map(g=>`#${g}`).join(', '))}\n${p.bpm} BPM ${esc(p.musical_key)}`;const r=await telegram(env,'sendAudio',{chat_id:chat,audio:url,title:p.title,performer:'Nexora',caption,parse_mode:'HTML',reply_markup:{inline_keyboard:[[{text:'✅ Опубликовать',callback_data:'upload:publish'}],[{text:'✏️ Редактировать',callback_data:'upload:edit'}],[{text:'❌ Отменить',callback_data:'flow:cancel'}]]}});await setSession(env,a.telegram_user_id,'upload_preview',{...p,last_preview_message_id:r.message_id})}
async function publish(env,a,p){const common={title:p.title,audio_path:p.audio_path,genre:p.genres.join(', '),bpm:p.bpm,musical_key:p.musical_key,published:true};if(p.type==='artist')await supabase(env,'/rest/v1/tracks',{method:'POST',body:JSON.stringify({...common,owner_id:a.profile_id})});else await supabase(env,'/rest/v1/beats',{method:'POST',body:JSON.stringify({...common,beatmaker_id:a.profile_id,price_cents:0})})}
async function library(env,chat,a,type,page,messageId=null){const table=type==='tracks'?'tracks':'beats',owner=type==='tracks'?'owner_id':'beatmaker_id';const rows=await supabase(env,`/rest/v1/${table}?${owner}=eq.${a.profile_id}&select=id,title,genre,bpm,musical_key,created_at&order=created_at.desc&limit=10&offset=${page*10}`);let text=`${type==='tracks'?'🎵':'🥁'} <b>${type==='tracks'?'Мои демки':'Мои биты'}</b>\n\n`;if(!rows?.length)text+=page?'Больше ничего нет.':'Пока ничего не загружено.';(rows||[]).forEach((x,i)=>text+=`${i+1}. <b>${esc(x.title)}</b> — ${esc(x.genre||'без жанра')} · ${x.bpm||'?'} BPM ${esc(x.musical_key||'')}\n`);const b=(rows||[]).map(x=>[{text:x.title.slice(0,45),callback_data:`library:item:${type}:${x.id}`}]);const nav=[];if(page>0)nav.push({text:'⬅️ Назад',callback_data:`library:${type}:${page-1}`});if((rows||[]).length===10)nav.push({text:'Вперёд ➡️',callback_data:`library:${type}:${page+1}`});if(nav.length)b.push(nav);b.push([{text:'👤 Профиль',callback_data:'profile:show'}]);if(messageId)return telegram(env,'editMessageText',{chat_id:chat,message_id:messageId,text,parse_mode:'HTML',reply_markup:{inline_keyboard:b}});return send(env,chat,text,{inline_keyboard:b},a)}
async function libraryItem(env,chat,a,type,id){const table=type==='tracks'?'tracks':'beats',owner=type==='tracks'?'owner_id':'beatmaker_id';const x=(await supabase(env,`/rest/v1/${table}?id=eq.${id}&${owner}=eq.${a.profile_id}&select=*`))?.[0];if(!x)return send(env,chat,'Файл не найден.',null,a);const url=`${env.SUPABASE_URL}/storage/v1/object/public/nexora-audio/${x.audio_path}`;return telegram(env,'sendAudio',{chat_id:chat,audio:url,title:x.title,performer:'Nexora',caption:`${type==='tracks'?'🎵':'🥁'} <b>${esc(x.title)}</b>\n${esc(x.genre||'')}\n${x.bpm||'?'} BPM ${esc(x.musical_key||'')}`,parse_mode:'HTML',reply_markup:{inline_keyboard:[[{text:'🗑 Удалить',callback_data:`library:delete:${type}:${x.id}`},{text:'⬅️ Назад',callback_data:`library:${type}:0`}]]}})}
async function deleteItem(env,chat,a,type,id){const table=type==='tracks'?'tracks':'beats',owner=type==='tracks'?'owner_id':'beatmaker_id';const x=(await supabase(env,`/rest/v1/${table}?id=eq.${id}&${owner}=eq.${a.profile_id}&select=audio_path`))?.[0];if(!x)return send(env,chat,'Файл не найден.',null,a);await supabase(env,`/rest/v1/${table}?id=eq.${id}&${owner}=eq.${a.profile_id}`,{method:'DELETE'});await supabase(env,`/storage/v1/object/nexora-audio/${x.audio_path}`,{method:'DELETE'}).catch(()=>null);return send(env,chat,'🗑 <b>Удалено.</b>',{inline_keyboard:[[{text:'⬅️ В список',callback_data:`library:${type}:0`},{text:'👤 Профиль',callback_data:'profile:show'}]]},a)}
async function randomPicker(env,chat,a,type,messageId=null){await setSession(env,a.telegram_user_id,'random_genre',{type});const text=`🎲 <b>Случайные ${type==='tracks'?'демки':'биты'}</b>\n\nВведи жанр или выбери любой.`;const markup={inline_keyboard:[[{text:'🎲 Любой жанр',callback_data:`random:any:${type}`}],[{text:'❌ Отменить',callback_data:'flow:cancel'}]]};if(messageId)return telegram(env,'editMessageText',{chat_id:chat,message_id:messageId,text,parse_mode:'HTML',reply_markup:markup});return send(env,chat,text,markup,a)}
async function randomContent(env,chat,a,type,genre=null){const table=type==='tracks'?'tracks':'beats',owner=type==='tracks'?'owner_id':'beatmaker_id';let q=`/rest/v1/${table}?published=eq.true&select=*&limit=50`;if(genre)q+=`&genre=ilike.*${encodeURIComponent(genre)}*`;const rows=await supabase(env,q),pool=(rows||[]).filter(x=>x[owner]!==a.profile_id);if(!pool.length)return send(env,chat,'По этому фильтру ничего не найдено.',{inline_keyboard:[[{text:'👤 Профиль',callback_data:'profile:show'}]]},a);const x=pool[Math.floor(Math.random()*pool.length)],url=`${env.SUPABASE_URL}/storage/v1/object/public/nexora-audio/${x.audio_path}`;const kb=type==='tracks'?[[{text:'❤️ Like',callback_data:`like:t:${x.id}`},{text:'🤝 Коллаб',callback_data:`collab:${x.id}:${x.owner_id}`}],[{text:'🎲 Ещё',callback_data:'random:tracks'},{text:'👤 Профиль',callback_data:'profile:show'}]]:[[ {text:'❤️ Like',callback_data:`like:b:${x.id}`},{text:'💳 Купить',callback_data:`buy:${x.id}`}],[{text:'🤝 Предложить',callback_data:`offer:${x.id}:${x.beatmaker_id}`}],[{text:'🎲 Ещё',callback_data:'random:beats'},{text:'👤 Профиль',callback_data:'profile:show'}]];return telegram(env,'sendAudio',{chat_id:chat,audio:url,title:x.title,performer:'Nexora',caption:`${type==='tracks'?'🎧':'🥁'} <b>${esc(x.title)}</b>\n${esc(x.genre||'')}\n${x.bpm||'?'} BPM ${esc(x.musical_key||'')}`,parse_mode:'HTML',reply_markup:{inline_keyboard:kb}})}
async function callback(env,q,a){const chat=q.message?.chat?.id,mid=q.message?.message_id,d=q.data||'';await telegram(env,'answerCallbackQuery',{callback_query_id:q.id}).catch(()=>null);if(d==='flow:cancel'){await setSession(env,a.telegram_user_id,'idle',{});return showProfile(env,chat,a,mid)}if(d.startsWith('reg:type:')){const t=d.split(':')[2];await setSession(env,a.telegram_user_id,'registration_username',{profile_type:t,message_id:mid});return telegram(env,'editMessageText',{chat_id:chat,message_id:mid,text:`Тип: <b>${typeLabel(t)}</b>\n\nВведи уникальный ник профиля.`,parse_mode:'HTML',reply_markup:cancel()})}if(d==='profile:show')return showProfile(env,chat,a,mid);if(d==='profile:edit')return registration(env,chat,a,mid);if(d==='profile:channel'){await setSession(env,a.telegram_user_id,'awaiting_channel',{message_id:mid});return telegram(env,'editMessageText',{chat_id:chat,message_id:mid,text:'📢 <b>Telegram-канал</b>\n\nОтправь канал в формате <b>@tgk</b>.',parse_mode:'HTML',reply_markup:cancel()})}if(d==='upload:start')return startUpload(env,chat,a);if(d==='upload:publish'){const s=await session(env,a.telegram_user_id);if(s.state!=='upload_preview')return send(env,chat,'Загрузка устарела.',null,a);await publish(env,a,s.payload);if(s.payload.last_preview_message_id)await del(env,chat,s.payload.last_preview_message_id);await setSession(env,a.telegram_user_id,'idle',{});return showProfile(env,chat,a)}if(d==='upload:edit'){const s=await session(env,a.telegram_user_id);await setSession(env,a.telegram_user_id,'awaiting_genres',{...s.payload,message_id:mid});return telegram(env,'editMessageText',{chat_id:chat,message_id:mid,text:'✏️ Введи жанры одной строкой:\n\n<code>#жанр1, #жанр2</code>',parse_mode:'HTML',reply_markup:cancel()})}if(d.startsWith('library:tracks:'))return library(env,chat,a,'tracks',+d.split(':')[2]||0,mid);if(d.startsWith('library:beats:'))return library(env,chat,a,'beats',+d.split(':')[2]||0,mid);if(d.startsWith('library:item:')){const[, ,t,id]=d.split(':');return libraryItem(env,chat,a,t,id)}if(d.startsWith('library:delete:')){const[, ,t,id]=d.split(':');return deleteItem(env,chat,a,t,id)}if(d==='random:tracks')return randomPicker(env,chat,a,'tracks',mid);if(d==='random:beats')return randomPicker(env,chat,a,'beats',mid);if(d.startsWith('random:any:')){const t=d.split(':')[2];await setSession(env,a.telegram_user_id,'idle',{});return randomContent(env,chat,a,t)}if(d.startsWith('like:t:')){await supabase(env,'/rest/v1/track_likes',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify({user_id:a.profile_id,track_id:d.split(':')[2]})});return}if(d.startsWith('like:b:')){await supabase(env,'/rest/v1/beat_likes',{method:'POST',headers:{Prefer:'resolution=ignore-duplicates,return=minimal'},body:JSON.stringify({user_id:a.profile_id,beat_id:d.split(':')[2]})});return}if(d.startsWith('collab:')){const[,trackId,recipientId]=d.split(':');await setSession(env,a.telegram_user_id,'awaiting_collab',{track_id:trackId,recipient_id:recipientId});return send(env,chat,'🤝 Напиши сообщение автору демки.',cancel(),a)}if(d.startsWith('offer:')){const[,beatId,recipientId]=d.split(':');await setSession(env,a.telegram_user_id,'awaiting_offer',{beat_id:beatId,recipient_id:recipientId});return send(env,chat,'🤝 Напиши сообщение битмейкеру.',cancel(),a)}if(d.startsWith('buy:')){const b=(await supabase(env,`/rest/v1/beats?id=eq.${d.split(':')[1]}&select=id,title,beatmaker_id,price_cents`))?.[0];if(!b)return send(env,chat,'Бит не найден.',null,a);await supabase(env,'/rest/v1/beat_orders',{method:'POST',body:JSON.stringify({beat_id:b.id,buyer_id:a.profile_id,seller_id:b.beatmaker_id,price_cents:b.price_cents||0,status:'pending',license_type:'standard'})});return}if(d.startsWith('requests:'))return send(env,chat,'Этот раздел уже заложен в структуру. Механику входящих запросов допишем по оставшейся части ТЗ.',{inline_keyboard:[[{text:'👤 Профиль',callback_data:'profile:show'}]]},a)}
async function handleText(env,msg,a){const chat=msg.chat.id,text=(msg.text||'').trim(),s=await session(env,a.telegram_user_id);if(text==='/start'){await del(env,chat,msg.message_id);return startRegistration(env,chat,a)}if(s.state==='registration_username'){await del(env,chat,msg.message_id);const u=text.replace(/^@/,'').trim();if(!/^[a-zA-Z0-9_.-]{3,32}$/.test(u))return send(env,chat,'Ник: 3–32 символа, латиница, цифры, `_`, `-`, `.`.',cancel(),a);try{await updateProfile(env,a,{username:u,display_name:u,profile_type:s.payload.profile_type})}catch(e){if(String(e.message).includes('409')||String(e.message).toLowerCase().includes('duplicate'))return send(env,chat,'Этот ник уже занят. Введи другой.',cancel(),a);throw e}return showProfile(env,chat,a)}if(s.state==='awaiting_channel'){await del(env,chat,msg.message_id);const c=text.replace(/^https?:\/\/(t\.me\/)?/,'').trim();if(!/^@[A-Za-z0-9_]{4,32}$/.test(c))return send(env,chat,'Нужен формат <b>@tgk</b>.',cancel(),a);await updateProfile(env,a,{telegram_channel:c});return showProfile(env,chat,a)}if(s.state==='awaiting_upload')return send(env,chat,'Пришли именно MP3-файл.',cancel(),a);if(s.state==='awaiting_title'){await del(env,chat,msg.message_id);if(!text||text.length>160)return send(env,chat,'Название от 1 до 160 символов.',cancel(),a);await setSession(env,a.telegram_user_id,'awaiting_genres',{...s.payload,title:text});return send(env,chat,'Теперь введи жанры:\n\n<code>#жанр1, #жанр2</code>',cancel(),a)}if(s.state==='awaiting_genres'){await del(env,chat,msg.message_id);const genres=parseGenres(text);if(!genres.length)return send(env,chat,'Укажи хотя бы один жанр через запятую.',cancel(),a);await setSession(env,a.telegram_user_id,'awaiting_bpmkey',{...s.payload,genres});return send(env,chat,'Теперь введи BPM и тональность:\n\n<code>140BPM Cmin</code>',cancel(),a)}if(s.state==='awaiting_bpmkey'){await del(env,chat,msg.message_id);const m=parseBpmKey(text);if(!m)return send(env,chat,'Формат: <code>140BPM Cmin</code>.',cancel(),a);await setSession(env,a.telegram_user_id,'upload_preview',{...s.payload,...m});return uploadPreview(env,chat,a)}if(s.state==='random_genre'){await del(env,chat,msg.message_id);await setSession(env,a.telegram_user_id,'idle',{});return randomContent(env,chat,a,s.payload.type,text.replace(/^#/,'').trim())}if(s.state==='awaiting_collab'){await del(env,chat,msg.message_id);await supabase(env,'/rest/v1/collab_requests',{method:'POST',body:JSON.stringify({requester_id:a.profile_id,recipient_id:s.payload.recipient_id,track_id:s.payload.track_id,role:'collaborator',message:text.slice(0,2000),status:'pending'})});await setSession(env,a.telegram_user_id,'idle',{});return showProfile(env,chat,a)}if(s.state==='awaiting_offer'){await del(env,chat,msg.message_id);await supabase(env,'/rest/v1/beat_offers',{method:'POST',body:JSON.stringify({sender_id:a.profile_id,recipient_id:s.payload.recipient_id,beat_id:s.payload.beat_id,message:text.slice(0,2000),status:'pending'})});await setSession(env,a.telegram_user_id,'idle',{});return showProfile(env,chat,a)}return showProfile(env,chat,a)}
